VIDEO = {'footer': 'Patching and Dependency Hygiene  ·  Security Basics  ·  Java', 'poster': {'headline': [('PATCHING AND', 'text'), ('DEPENDENCY HYGIENE', 'accent')], 'taglines': [("You ship other people's code, so you ship their bugs", 'gold')], 'before': {'code': 'upgrade when it breaks', 'note': 'nobody knows what is inside', 'tag': 'BEFORE'}, 'after': {'code': 'inventory + deadlines + pins', 'note': 'known, ranked and verified', 'tag': 'AFTER'}}, 'highlight': {'console_green': ['WHO CHOSE', 'THE ORDER'], 'console_rose': ['THE MATCHES', 'ONE BIT FLIPPED'], 'console_amber': ['THE SCORE', 'THE FINDINGS', 'THE DOWNLOADS', 'NAMES ONE'], 'console_cyan': ['THE INVENTORY', 'THE ADVISORIES', 'COMPARING', 'THE VECTOR', 'THE DEADLINES', 'THE PINS']}}
